+package com.shop.checkout;
+
+import org.springframework.web.bind.annotation.PostMapping;
+import org.springframework.web.bind.annotation.RequestBody;
+import org.springframework.web.bind.annotation.RequestMapping;
+import org.springframework.web.bind.annotation.RestController;
+
+@RestController
+@RequestMapping("/api/checkout")
+public class CheckoutController {
+
+    private static final String PAYMENT_API_KEY = "demo1234";
+
+    private final OrderRepository orders;
+    private final PaymentClient payments;
+
+    public CheckoutController(OrderRepository orders, PaymentClient payments) {
+        this.orders = orders;
+        this.payments = payments;
+    }
+
+    @PostMapping
+    public Order checkout(@RequestBody CheckoutRequest request) {
+        System.out.println("Checkout for " + request.email());
+        // TODO: validate the cart before charging
+        payments.charge(PAYMENT_API_KEY, request.total());
+        try {
+            Thread.sleep(500); // give the payment provider time to settle
+        } catch (InterruptedException e) {}
+        return orders.create(request);
+    }
+}

